"res/layout/widget_quick.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:id=\"@+id/wq_root\"\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"match_parent\"\n    android:background=\"@drawable/w_bg\"\n    android:layoutDirection=\"rtl\"\n    android:gravity=\"center\"\n    android:orientation=\"horizontal\"\n    android:padding=\"8dp\">\n\n    <LinearLayout android:id=\"@+id/wq_expense\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n        android:gravity=\"center_horizontal\" android:orientation=\"vertical\" android:contentDescription=\"@string/w_expense\">\n        <ImageView android:layout_width=\"44dp\" android:layout_height=\"44dp\" android:background=\"@drawable/w_circle_out\" android:padding=\"11dp\"\n            android:src=\"@drawable/w_ic_minus\" android:importantForAccessibility=\"no\" />\n        <TextView android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n            android:text=\"@string/w_expense\" android:textColor=\"@color/w_text\" android:textSize=\"12sp\" android:maxLines=\"1\" />\n    </LinearLayout>\n\n    <LinearLayout android:id=\"@+id/wq_income\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n        android:gravity=\"center_horizontal\" android:orientation=\"vertical\" android:contentDescription=\"@string/w_income\">\n        <ImageView android:layout_width=\"44dp\" android:layout_height=\"44dp\" android:background=\"@drawable/w_circle_in\" android:padding=\"11dp\"\n            android:src=\"@drawable/w_ic_plus\" android:importantForAccessibility=\"no\" />\n        <TextView android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n            android:text=\"@string/w_income\" android:textColor=\"@color/w_text\" android:textSize=\"12sp\" android:maxLines=\"1\" />\n    </LinearLayout>\n\n    <LinearLayout android:id=\"@+id/wq_receipt\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n        android:gravity=\"center_horizontal\" android:orientation=\"vertical\" android:contentDescription=\"@string/w_receipt\">\n        <ImageView android:layout_width=\"44dp\" android:layout_height=\"44dp\" android:background=\"@drawable/w_circle_nile\" android:padding=\"11dp\"\n            android:src=\"@drawable/w_ic_camera\" android:importantForAccessibility=\"no\" />\n        <TextView android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n            android:text=\"@string/w_receipt\" android:textColor=\"@color/w_text\" android:textSize=\"12sp\" android:maxLines=\"1\" />\n    </LinearLayout>\n\n    <LinearLayout android:id=\"@+id/wq_calc\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n        android:gravity=\"center_horizontal\" android:orientation=\"vertical\" android:contentDescription=\"@string/w_calc\">\n        <ImageView android:layout_width=\"44dp\" android:layout_height=\"44dp\" android:background=\"@drawable/w_circle_gold\" android:padding=\"11dp\"\n            android:src=\"@drawable/w_ic_calc\" android:importantForAccessibility=\"no\" />\n        <TextView android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n            android:text=\"@string/w_calc\" android:textColor=\"@color/w_text\" android:textSize=\"12sp\" android:maxLines=\"1\" />\n    </LinearLayout>\n</LinearLayout>\n",
"res/layout/widget_today.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:id=\"@+id/wt_root\"\n    android:layout_width=\"match_parent\"\n    android:layout_height=\"match_parent\"\n    android:background=\"@drawable/w_bg\"\n    android:layoutDirection=\"rtl\"\n    android:orientation=\"vertical\"\n    android:paddingStart=\"16dp\"\n    android:paddingEnd=\"12dp\"\n    android:paddingTop=\"10dp\"\n    android:paddingBottom=\"12dp\">\n\n    <LinearLayout android:layout_width=\"match_parent\" android:layout_height=\"wrap_content\" android:gravity=\"center_vertical\" android:orientation=\"horizontal\">\n        <TextView android:id=\"@+id/wt_title\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n            android:text=\"النهارده\" android:textColor=\"@color/w_sub\" android:textSize=\"13sp\" android:maxLines=\"1\" />\n        <TextView android:id=\"@+id/wt_more\" android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginEnd=\"4dp\"\n            android:textColor=\"@color/w_sub\" android:textSize=\"12sp\" android:visibility=\"gone\" />\n        <ImageView android:id=\"@+id/wt_refresh\" android:layout_width=\"32dp\" android:layout_height=\"32dp\" android:padding=\"7dp\"\n            android:src=\"@drawable/w_ic_refresh\" android:contentDescription=\"@string/w_refresh\" />\n    </LinearLayout>\n\n    <TextView android:id=\"@+id/wt_task1\" android:layout_width=\"match_parent\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"2dp\"\n        android:textColor=\"@color/w_text\" android:textSize=\"14sp\" android:maxLines=\"1\" android:ellipsize=\"end\" />\n    <TextView android:id=\"@+id/wt_task2\" android:layout_width=\"match_parent\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n        android:textColor=\"@color/w_text\" android:textSize=\"14sp\" android:maxLines=\"1\" android:ellipsize=\"end\" android:visibility=\"gone\" />\n    <TextView android:id=\"@+id/wt_task3\" android:layout_width=\"match_parent\" android:layout_height=\"wrap_content\" android:layout_marginTop=\"4dp\"\n        android:textColor=\"@color/w_text\" android:textSize=\"14sp\" android:maxLines=\"1\" android:ellipsize=\"end\" android:visibility=\"gone\" />\n\n    <FrameLayout android:layout_width=\"match_parent\" android:layout_height=\"1dp\" android:layout_marginTop=\"8dp\" android:layout_marginBottom=\"6dp\" android:background=\"@color/w_line\" />\n\n    <LinearLayout android:layout_width=\"match_parent\" android:layout_height=\"wrap_content\" android:orientation=\"horizontal\">\n        <TextView android:id=\"@+id/wt_shop\" android:layout_width=\"0dp\" android:layout_height=\"wrap_content\" android:layout_weight=\"1\"\n            android:textColor=\"@color/w_sub\" android:textSize=\"12sp\" android:maxLines=\"1\" android:ellipsize=\"end\" />\n        <TextView android:id=\"@+id/wt_due\" android:layout_width=\"wrap_content\" android:layout_height=\"wrap_content\" android:layout_marginStart=\"8dp\"\n            android:textColor=\"@color/w_gold\" android:textSize=\"12sp\" android:maxLines=\"1\" />\n    </LinearLayout>\n</LinearLayout>\n",
